WITH src AS (SELECT * FROM shipments WHERE shipped_date < '2025-08-01'), status_group_summary AS (SELECT CASE WHEN status IN ('RETURNED', 'IN_TRANSIT') THEN 'tier_1' ELSE 'other' END status_group, COUNT(CASE WHEN carrier = 'FedEx' THEN 1 END) fedex_count FROM src GROUP BY CASE WHEN status IN ('RETURNED', 'IN_TRANSIT') THEN 'tier_1' ELSE 'other' END) SELECT status_group, fedex_count FROM status_group_summary WHERE fedex_count >= 6 ORDER BY fedex_count
